-- Datos de desarrollo. No crea usuarios Auth ni contiene contraseñas.
-- IDs fijos para que el seed sea reproducible.

values ('10000000-0000-4000-8000-000000000001', 'Marisquería Pacífico', 'marisqueria-pacifico')
on conflict (id) do update set name = excluded.name;

values (
  '20000000-0000-4000-8000-000000000001',
  '10000000-0000-4000-8000-000000000001',
  'Marisquería Pacífico',
  'pacifico-cdmx',
  '{"city":"Ciudad de México","country":"MX"}',
  '+52 55 0000 0000'
)
on conflict (id) do update set name = excluded.name;

on conflict (organization_id, code) do update set description = excluded.description;

on conflict (organization_id, code) do update set name = excluded.name;

select '10000000-0000-4000-8000-000000000001', role.id, permission.id
from public.roles role cross join public.permissions permission
where role.id = '40000000-0000-4000-8000-000000000001'
on conflict do nothing;

select '10000000-0000-4000-8000-000000000001', role.id, permission.id
from public.roles role join public.permissions permission on permission.code in ('branches.all','users.read','data.write','audit.read')
where role.id = '40000000-0000-4000-8000-000000000002'
on conflict do nothing;

select '10000000-0000-4000-8000-000000000001', role.id, permission.id
from public.roles role join public.permissions permission on permission.code = 'data.write'
where role.code in ('captain','waiter','cashier','cold_kitchen','hot_kitchen','bar','runner','host')
on conflict do nothing;

on conflict (branch_id, name) do update set sort_order = excluded.sort_order;

select
  ('60000000-0000-4000-8000-' || lpad(number::text, 12, '0'))::uuid,
  '10000000-0000-4000-8000-000000000001',
  '20000000-0000-4000-8000-000000000001',
  case when number <= 6 then '50000000-0000-4000-8000-000000000001'::uuid when number <= 10 then '50000000-0000-4000-8000-000000000002'::uuid else '50000000-0000-4000-8000-000000000003'::uuid end,
  'Mesa ' || number,
  case when number in (3,7) then 6 else 4 end,
  ((number - 1) % 4) * 150,
  floor((number - 1) / 4) * 120,
  number
from generate_series(1, 12) number
on conflict (branch_id, name) do update set capacity = excluded.capacity;

on conflict (branch_id, station_type) do update set name = excluded.name;

on conflict (branch_id, name) do update set sort_order = excluded.sort_order;

on conflict (branch_id, sku) do update set name = excluded.name, price_cents = excluded.price_cents;

on conflict (id) do nothing;


select '10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001', item.id, group_id, row_number() over (partition by item.id order by group_id)
from public.menu_items item cross join unnest(array['a0000000-0000-4000-8000-000000000001'::uuid,'a0000000-0000-4000-8000-000000000002'::uuid]) group_id
where item.branch_id = '20000000-0000-4000-8000-000000000001' and item.station_id <> '70000000-0000-4000-8000-000000000003'
on conflict do nothing;

on conflict (branch_id, name) do update set stock_quantity = excluded.stock_quantity;

on conflict (menu_item_id, ingredient_id) do update set quantity = excluded.quantity;

